import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { SignDatabase } from "../src/sign-database.js";

const file = join(import.meta.dirname, "../data/sign-info.json");

// The data is generated by `./gradlew :jseshJsExport:exportSignInfo`.
describe.skipIf(!existsSync(file))("SignDatabase", () => {
  const db = new SignDatabase(JSON.parse(readFileSync(file, "utf-8")));

  it("lists the families in JSesh's order", () => {
    expect(db.getFamilies()[0]).toEqual({ code: "A", description: "Man and his occupations" });
    expect(db.getFamilies().map((f) => f.code)).toContain("Aa");
  });

  it("lists a family with or without its variants", () => {
    const all = db.getCodesForFamily("A", true);
    const basic = db.getCodesForFamily("A", false);
    expect(all.slice(0, 2)).toEqual(["A1", "A1A"]);
    expect(basic).toContain("A1");
    expect(basic).not.toContain("A1A");
    expect(basic.length).toBeLessThan(all.length);
    expect(db.getCodesForFamily("A", true)).not.toContain("Aa1");
  });

  it("gives values, tags, variants and parts", () => {
    expect(db.getValuesFor("A1")).toContain("i");
    expect(db.getTagsForSign("A1")).toContain("seated");
    expect(db.getVariants("A1").map((v) => v.code)).toContain("A1B");
    expect(db.getPossibilityFor("nfr")[0]).toBe("F35");
    const container = db.getCodesSet().find((c) => db.getSignsIn(c).length > 0)!;
    expect(db.getSignsContaining(db.getSignsIn(container)[0]!)).toContain(container);
  });

  it("finds codes as JSesh does", () => {
    expect(db.getSuitableSignsForCode("a1")[0]).toBe("A1");
    expect(db.getSuitableSignsForCode("a1")).toContain("A1A");
    expect(db.getSuitableSignsForCode("a1")).not.toContain("A10");
    expect(db.getCodesStartingWith("A1")).toContain("A10");
    expect(db.compareCodes("A2", "A10")).toBeLessThan(0);
  });

  it("lists the possibilities for a code as the editor does", () => {
    // Phonetic value: the official code first, then the signs with this value.
    expect(db.getPossibilityListFor("i").slice(0, 3)).toEqual(["i", "A1", "A26"]);
    expect(db.getPossibilityListFor("m-n")).toEqual(db.getPossibilityListFor("mn"));
    // Gardiner code, in any case.
    expect(db.getPossibilityListFor("a1")[0]).toBe("A1");
    expect(db.getPossibilityListFor("a1")).toContain("A1A");
    // Unknown.
    expect(db.getPossibilityListFor("zzzz")).toEqual(["zzzz"]);
  });
});
